use std::cell::RefCell;

thread_local! {
    static CTX: RefCell<Option<RequestContext>> = const { RefCell::new(None) };
}

pub fn with_ctx<R>(f: impl FnOnce(&RequestContext) -> R) -> Option<R> {
    CTX.with(|cell| cell.borrow().as_ref().map(f))   // try_with survives TLS destruction
}

